/**
 * Sets whether to throw an exception when maxDepth is reached.
 *
 * @param throwOnMaxDepth true to throw an exception
 */
public void setThrowOnMaxDepth(boolean throwOnMaxDepth) {
    this.throwOnMaxDepth = throwOnMaxDepth;
}
